import type { HeadConfig } from '@vuepress/shared'

import { renderHeadAttrs } from './renderHeadAttrs.js'

/**
 * Escape a string to be used as html text content
 *
 * The `&` must be escaped first, otherwise the entities generated by the
 * following replacements would be escaped again.
 */
const escapeTextContent = (value: unknown): string =>
  String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')

/**
 * Render head config to string
 *
 * The inner html is rendered by tag semantics instead of being escaped
 * blindly:
 *
 * - `title` is an "escapable raw text" element, its content must be escaped
 *   as html text, otherwise `</title>` in the content would break out of the
 *   element and allow injecting arbitrary html.
 * - `script` and `style` are "raw text" elements, their content must be kept
 *   as-is, otherwise the js / css code would be broken by escaping.
 * - `template` and `noscript` contain html fragments, their content must be
 *   kept as-is so that the html is still parsed as elements.
 *
 * Notice that on the client side, `createHeadElement` in
 * `packages/client/src/setupUpdateHead.ts` uses `setAttribute` for attributes
 * and `createTextNode` for content, which store raw values and are escaped
 * automatically by the dom apis. On the server side, the head is rendered as a
 * plain string, so escaping has to be done manually here. The escaped output
 * is equivalent to the raw value once it is parsed by the browser, which keeps
 * the server-rendered head consistent with the client-updated head.
 */
export const renderHead = ([
  tag,
  attrs,
  innerHTML = '',
]: HeadConfig): string => {
  const openTag = `<${tag}${renderHeadAttrs(attrs)}>`
  if (tag === 'link' || tag === 'meta' || tag === 'base') {
    return openTag
  }
  const renderedInnerHTML =
    tag === 'title' ? escapeTextContent(innerHTML) : innerHTML
  return `${openTag}${renderedInnerHTML}</${tag}>`
}
